func newArtifact() unsafe.Pointer { return unsafe.Pointer(new(assistantartifact.Artifact)) }

func newNArtifact(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]assistantartifact.Artifact, n)))
}

func ptrArtifact(p unsafe.Pointer, c int32) any {
	r := (*assistantartifact.Artifact)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ThreadID))
	case 4:
		return (*string)(unsafe.Pointer(&r.MessageID))
	case 5:
		return (*string)(unsafe.Pointer(&r.RunID))
	case 6:
		return (*string)(unsafe.Pointer(&r.ProposalID))
	case 7:
		return (*string)(unsafe.Pointer(&r.PlanID))
	case 8:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return &r.Title
	case 11:
		return &r.Payload
	case 12:
		return &r.SourceToolCallID
	case 13:
		return &r.Pinned
	case 14:
		return &r.LineageKey
	case 15:
		return (*string)(unsafe.Pointer(&r.LineageID))
	case 16:
		return (*int64)(unsafe.Pointer(&r.LineageSeq))
	case 17:
		return &r.Slug
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueArtifact(p unsafe.Pointer, c int32) any {
	r := (*assistantartifact.Artifact)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ThreadID)
	case 4:
		if r.MessageID == "" {
			return nil
		}
		return string(r.MessageID)
	case 5:
		if r.RunID == "" {
			return nil
		}
		return string(r.RunID)
	case 6:
		if r.ProposalID == "" {
			return nil
		}
		return string(r.ProposalID)
	case 7:
		if r.PlanID == "" {
			return nil
		}
		return string(r.PlanID)
	case 8:
		return string(r.Kind)
	case 9:
		return string(r.Status)
	case 10:
		return r.Title
	case 11:
		if r.Payload == nil {
			return keel.EmptyJSONObject
		}
		return r.Payload
	case 12:
		return r.SourceToolCallID
	case 13:
		return r.Pinned
	case 14:
		return r.LineageKey
	case 15:
		if r.LineageID == "" {
			return nil
		}
		return string(r.LineageID)
	case 16:
		return int64(r.LineageSeq)
	case 17:
		return r.Slug
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

